    <div class="flex gap-4 border-b border-white/10"><button type="button" data-quadro-member-tab="accepted" aria-pressed="true" class="border-b-2 border-transparent pb-3 text-sm text-slate-400 aria-pressed:border-indigo-400 aria-pressed:text-indigo-200">Membros · {{ $quadro->membros->where('status', 'accepted')->count() + 1 }}</button><button type="button" data-quadro-member-tab="pending" aria-pressed="false" class="border-b-2 border-transparent pb-3 text-sm text-slate-400 aria-pressed:border-indigo-400 aria-pressed:text-indigo-200">Lista de espera · {{ $quadro->membros->where('status', 'pending')->count() }}</button></div>
